public String minWindow(String s, String t) {
    if (s.length() < t.length()) return "";
    int[] need = new int[128];
    int required = 0;
    for (char c : t.toCharArray()) { if (need[c]++ == 0) required++; }
    int[] have = new int[128];
    int formed = 0, left = 0, bestLen = Integer.MAX_VALUE, bestL = 0;
    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        if (++have[c] == need[c]) formed++;
        while (formed == required) {
            if (right - left + 1 < bestLen) { bestLen = right - left + 1; bestL = left; }
            char lc = s.charAt(left++);
            if (have[lc]-- == need[lc]) formed--;
        }
    }
    return bestLen == Integer.MAX_VALUE ? "" : s.substring(bestL, bestL + bestLen);
}

public int subarraysWithKDistinct(int[] nums, int k) {
    return atMost(nums, k) - atMost(nums, k - 1);
}

private int atMost(int[] nums, int k) {
    if (k < 0) return 0;
    int[] count = new int[nums.length + 1];
    int left = 0, distinct = 0, res = 0;
    for (int right = 0; right < nums.length; right++) {
        if (count[nums[right]]++ == 0) distinct++;
        while (distinct > k) {
            if (--count[nums[left]] == 0) distinct--;
            left++;
        }
        res += right - left + 1;
    }
    return res;
}

public int[] maxSlidingWindow(int[] nums, int k) {
    int n = nums.length;
    int[] res = new int[n - k + 1];
    Deque<Integer> dq = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        if (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();
        while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();
        dq.offerLast(i);
        if (i >= k - 1) res[i - k + 1] = nums[dq.peekFirst()];
    }
    return res;
}

public int lengthOfLongestSubstringKDistinct(String s, int k) {
    if (k == 0) return 0;
    Map<Character, Integer> count = new HashMap<>();
    int left = 0, best = 0;
    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        count.put(c, count.getOrDefault(c, 0) + 1);
        while (count.size() > k) {
            char lc = s.charAt(left++);
            int v = count.get(lc) - 1;
            if (v == 0) count.remove(lc); else count.put(lc, v);
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

public List<Integer> findSubstring(String s, String[] words) {
    List<Integer> res = new ArrayList<>();
    if (words.length == 0) return res;
    int wl = words[0].length(), n = words.length, total = wl * n;
    if (s.length() < total) return res;
    Map<String, Integer> need = new HashMap<>();
    for (String w : words) need.merge(w, 1, Integer::sum);
    for (int i = 0; i < wl; i++) {
        int left = i, count = 0;
        Map<String, Integer> window = new HashMap<>();
        for (int j = i; j + wl <= s.length(); j += wl) {
            String word = s.substring(j, j + wl);
            if (need.containsKey(word)) {
                window.merge(word, 1, Integer::sum);
                count++;
                while (window.get(word) > need.get(word)) {
                    String lw = s.substring(left, left + wl);
                    window.merge(lw, -1, Integer::sum);
                    left += wl;
                    count--;
                }
                if (count == n) {
                    res.add(left);
                    String lw = s.substring(left, left + wl);
                    window.merge(lw, -1, Integer::sum);
                    left += wl;
                    count--;
                }
            } else {
                window.clear();
                count = 0;
                left = j + wl;
            }
        }
    }
    return res;
}

public int minKBitFlips(int[] nums, int k) {
    int n = nums.length;
    int[] diff = new int[n + 1];
    int flips = 0, current = 0;
    for (int i = 0; i < n; i++) {
        current += diff[i];
        if (((nums[i] + current) & 1) == 0) {
            if (i + k > n) return -1;
            flips++;
            current++;
            diff[i + k]--;
        }
    }
    return flips;
}

public int numberOfSubarrays(int[] nums, int k) {
    return atMost(nums, k) - atMost(nums, k - 1);
}

private int atMost(int[] nums, int k) {
    if (k < 0) return 0;
    int left = 0, odd = 0, res = 0;
    for (int right = 0; right < nums.length; right++) {
        odd += nums[right] & 1;
        while (odd > k) odd -= nums[left++] & 1;
        res += right - left + 1;
    }
    return res;
}

public int balancedString(String s) {
    int n = s.length(), k = n / 4;
    int[] count = new int[128];
    for (char c : s.toCharArray()) count[c]++;
    if (count['Q'] <= k && count['W'] <= k && count['E'] <= k && count['R'] <= k) return 0;
    int left = 0, best = n;
    for (int right = 0; right < n; right++) {
        count[s.charAt(right)]--;
        while (left < n && count['Q'] <= k && count['W'] <= k && count['E'] <= k && count['R'] <= k) {
            best = Math.min(best, right - left + 1);
            count[s.charAt(left++)]++;
        }
    }
    return best;
}

public int longestSubstring(String s, int k) {
    int best = 0;
    for (int unique = 1; unique <= 26; unique++) {
        int[] count = new int[26];
        int left = 0, curUnique = 0, countAtLeastK = 0;
        for (int right = 0; right < s.length(); right++) {
            int r = s.charAt(right) - 'a';
            if (count[r]++ == 0) curUnique++;
            if (count[r] == k) countAtLeastK++;
            while (curUnique > unique) {
                int l = s.charAt(left++) - 'a';
                if (count[l] == k) countAtLeastK--;
                if (--count[l] == 0) curUnique--;
            }
            if (curUnique == unique && curUnique == countAtLeastK) {
                best = Math.max(best, right - left + 1);
            }
        }
    }
    return best;
}

public int longestSubstring(String s, int k) {
    return divide(s, 0, s.length(), k);
}

private int divide(String s, int start, int end, int k) {
    if (end - start < k) return 0;
    int[] count = new int[26];
    for (int i = start; i < end; i++) count[s.charAt(i) - 'a']++;
    for (int mid = start; mid < end; mid++) {
        if (count[s.charAt(mid) - 'a'] >= k) continue;
        int nextMid = mid + 1;
        while (nextMid < end && count[s.charAt(nextMid) - 'a'] < k) nextMid++;
        return Math.max(divide(s, start, mid, k), divide(s, nextMid, end, k));
    }
    return end - start;
}
